/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    str apiName = enum2str(XAPI_APIS::CreateContractPart);

    // DeliveryCategory - not created here, sourced from the value the Installation setup logged
    EXU_DeliveryCategory delCat = XAPI_AutomationHelper::getKeyValue(enum2str(XAPI_APIS::CreateInstallation), 'deliveryCategory');
    XAPI_AutomationHelper::logKeyValue(apiName, 'deliveryCategory', delCat);

    EXU_DeliveryGroupNum deliveryGroupNum = "TST_DeliveryGroup";
    EXU_ProductNum       productNum = "TST_Product";
    ItemId               itemId = "TST_Item";
    str                  priceManagementCode = "TST_PM";

    // Source - passed straight through to the API payload, no setup required
    str source = "TST_Source";
    XAPI_AutomationHelper::logKeyValue(apiName, 'Source', source);

    EXU_DeliveryGroupTable deliveryGroupTable, newDeliveryGroupTable;
    EXU_ProductTable       productTable, newProductTable;
    InventTable            inventTable;
    EXU_ProductExtendTable productExtendTable;

    select firstonly deliveryGroupTable;
    select firstonly newDeliveryGroupTable
        where newDeliveryGroupTable.DeliveryGroupNum == deliveryGroupNum;

    if (!newDeliveryGroupTable.RecId)
    {
        ttsbegin;
        buf2Buf(deliveryGroupTable, newDeliveryGroupTable);
        newDeliveryGroupTable.DeliveryCategory   = delCat;
        newDeliveryGroupTable.DeliveryGroupCode  = EXU_DeliveryGroupCode::RateCode;
        newDeliveryGroupTable.DeliveryGroupNum   = deliveryGroupNum;
        newDeliveryGroupTable.DeliveryGroupName  = deliveryGroupNum;
        newDeliveryGroupTable.EndDate            = dateMax();
        newDeliveryGroupTable.insert();
        ttscommit;

        info(strFmt("Inserted DeliveryGroupTable: %1", deliveryGroupNum));

        XAPI_AutomationHelper::logKeyValue(apiName, 'DeliveryGroupNum_RateCode', newDeliveryGroupTable.DeliveryGroupNum);
    }


    select firstonly productTable
        where productTable.RegistrationEndDate == dateNull();
    select firstonly newProductTable
        where newProductTable.ProductNum == productNum;

    if (!newProductTable.RecId)
    {
        ttsbegin;
        buf2Buf(productTable, newProductTable);
        newProductTable.CompanyId                  = curExt();
        newProductTable.DeliveryCategory           = delCat;
        newProductTable.ProductNum                 = productNum;
        newProductTable.DeliveryGroupNum_RateCode  = deliveryGroupNum;
        newProductTable.insert();
        ttscommit;

        info(strFmt("Inserted EXU_ProductTable: %1", productNum));

        XAPI_AutomationHelper::logKeyValue(apiName, 'ProductNum', newProductTable.ProductNum);
    }


    if (!InventTable::find(itemId))
    {
        ttsbegin;
        inventTable.clear();
        inventTable.initValue();
        inventTable.ItemId   = itemId;
        inventTable.ItemType = ItemType::Item;
        inventTable.insert();
        ttscommit;

        info(strFmt("Inserted InventTable: %1", itemId));

        XAPI_AutomationHelper::logKeyValue(apiName, 'ItemId', inventTable.ItemId);
    }


    select firstonly productExtendTable
        where productExtendTable.ProductNum          == productNum
           && productExtendTable.PriceManagementCode == priceManagementCode;

    if (!productExtendTable.RecId)
    {
        ttsbegin;
        productExtendTable.clear();
        productExtendTable.initValue();
        productExtendTable.ProductNum          = productNum;
        productExtendTable.PriceManagementCode = priceManagementCode;
        productExtendTable.ProductType         = itemId;
        productExtendTable.insert();
        ttscommit;

        info(strFmt("Inserted EXU_ProductExtendTable: %1 | %2",
            productNum, priceManagementCode));

        XAPI_AutomationHelper::logKeyValue(apiName, 'PriceManagementCode', productExtendTable.PriceManagementCode);
    }

}
